// Story 7-3 Types (Embedding)
export type EmbeddingVector = Float32Array;
export type EmbeddingMode = 'local' | 'cloud' | 'keyword-only';

export interface EmbeddingProgress {
  chunkId: string;
  currentChunk: number;
  totalChunks: number;
  status: 'embedding' | 'completed' | 'error';
  mode: EmbeddingMode;
  error?: string;
}

// Story 7-1 Types (Orama)
export interface DocumentSchema {
  id: string;
  sourceId: string;
  content: string;
  title?: string;
  position?: number;
  embedding?: number[];
  metadata?: {
    chunkIndex: number;
    totalChunks: number;
  };
}

export interface SearchResult {
  document: DocumentSchema;
  score: number;
  source: {
    id: string;
    title?: string;
  };
}

// Hybrid embedding service with device capability detection
export type EmbeddingProvider = 'local' | 'cloud' | 'none';

export interface BatchEmbeddingResult {
  results: EmbeddingResult[];
  totalLatencyMs: number;
  provider: EmbeddingProvider;
}

export async function detectDeviceCapabilities(): Promise<DeviceCapabilities> {
  // WebGPU detection, mobile detection, local model cache check
}

export async function createEmbeddingService(apiKey?: string): Promise<EmbeddingService> {
  // Auto-detects best provider (local/cloud/none)
  // Returns configured embedding service
}

// RAG State Management (Zustand)
interface RAGStore {
  // Index state
  indexStatus: IndexStatus;
  documentCount: number;
  indexMetadata: IndexMetadata | null;

  // Search cache
  searchCache: Map<string, SearchResult[]>;

  // Chunking state (Story 7-2)
  chunkingProgress: Map<string, ChunkingProgress>;

  // Embedding state (Story 7-3)
  embeddingProgress: Map<string, EmbeddingProgress>;
  embeddingMode: EmbeddingMode;

  // Actions
  detectEmbeddingCapability: () => Promise<EmbeddingMode>;
  generateEmbeddings: (chunks: ChunkMetadata[], options?: EmbeddingOptions) => Promise<Map<string, EmbeddingVector>>;
}
